/* evasion-to-guard-2026-11-12.macro.js — GENERATED by build-evasion-to-guard-macro.mjs; edit evasion-to-guard.mjs instead.
 * Dave 2026-11-12: "let's convert those evasion ones to guard". Every power / weapon (and any item hosting a bound Working) in
 * master-content + system Item packs, world items, items on world actors, items on actors in those Actor packs:
 * appliedEffects modifier stat evasion → guard; "Evasion" → "Guard" in effect / description / lore ("Evasion defense" → "Body defense").
 * Armor's own stats/text are NOT touched (its evasion folds into Guard higher-wins — the armor redesign owns it); a Working it hosts is.
 * Idempotent; DRY_RUN default true; GM only. Marker: [EVASION-TO-GUARD-2026-11-12] */
(async () => {
  const DRY_RUN = true;   // <-- set false to apply
  if (!game.user?.isGM) return ui.notifications.error("GM only.");
  function evasionToGuardUpdate(d) {
  const upd = {};
  const FAC = { violence: "Violence", intrigue: "Intrigue", presence: "Presence", body: "Body", mind: "Mind", soul: "Soul" };
  // "Evasion" naming a SAVE ("rolls Evasion vs DC 12", "Evasion check", "vs Evasion (DC 12)", "Evasion defense") → the faculty
  // the item actually rolls (resolution / appliedStates saveAttribute — foe packs store intrigue), else Body. Anywhere else → Guard.
  const facOf = (sys) => FAC[sys?.manifestation?.resolution?.saveAttribute] ?? FAC[sys?.manifestation?.appliedStates?.saveAttribute] ?? "Body";
  const word = (s, fac = "Body") => typeof s === "string"
    ? s.replace(/\bEvasion\b(?=\s*(?:<\/(?:strong|b|em)>)?\s*(?:check|defense|save|vs\.?\s*DC|\(DC))/g, fac)
       .replace(/\bEvasion\b/g, "Guard").replace(/\bevasion\b/g, "guard")
    : s;
  const one = (sys, base) => {
    if (!sys || typeof sys !== "object") return;
    const fac = facOf(sys);
    const mods = sys.manifestation?.appliedEffects?.modifiers;
    const hasMod = Array.isArray(mods) && mods.some(m => m?.stat === "evasion");
    const txt = [sys.effect, sys.description?.value, typeof sys.description === "string" ? sys.description : null];
    const hasText = txt.some(t => typeof t === "string" && /\bEvasion\b/.test(t));
    if (!hasMod && !hasText) return;
    if (hasMod) upd[`${base}.manifestation.appliedEffects.modifiers`] = mods.map(m => m?.stat === "evasion" ? { ...m, stat: "guard" } : m);
    if (typeof sys.effect === "string" && word(sys.effect, fac) !== sys.effect) upd[`${base}.effect`] = word(sys.effect, fac);
    if (typeof sys.description?.value === "string" && word(sys.description.value, fac) !== sys.description.value) upd[`${base}.description.value`] = word(sys.description.value, fac);
    else if (typeof sys.description === "string" && word(sys.description, fac) !== sys.description) upd[`${base}.description`] = word(sys.description, fac);
  };
  if (d.type === "power" || d.type === "weapon") {
    one(d.system, "system");
    const lore = d.flags?.fourththing?.rfi?.item?.lore;   // Brass Knife's rules line lives in its lore too
    if (typeof lore === "string" && word(lore, facOf(d.system)) !== lore) upd["flags.fourththing.rfi.item.lore"] = word(lore, facOf(d.system));
  }
  const w = d.flags?.fourththing?.working?.power;
  if (w?.system) one(w.system, "flags.fourththing.working.power.system");
  return Object.keys(upd).length ? upd : null;
}
  let changes = 0; const report = [];
  const updFor = (it) => evasionToGuardUpdate(it.toObject());   // armor's own stats are never touched; only a bound Working it hosts
  const doItems = (items, where) => { const rows = []; for (const it of items) { const u = updFor(it); if (u) { rows.push({ _id: it.id, ...u }); report.push(`${where} · ${it.name}: ${Object.keys(u).map(k => k.split(".").slice(-2).join(".")).join(", ")}`); } } changes += rows.length; return rows; };
  const mine = (p) => ["bbttcc-master-content", "fourththing"].includes(p.metadata.packageName);
  const unlockedWrite = async (pack, fn) => { const was = pack.locked; if (was) await pack.configure({ locked: false }); try { await fn(); } finally { if (was) await pack.configure({ locked: true }); } };
  for (const pack of game.packs.filter(p => mine(p) && p.documentName === "Item")) {
    const rows = doItems(await pack.getDocuments(), pack.metadata.label);
    if (rows.length && !DRY_RUN) await unlockedWrite(pack, () => Item.updateDocuments(rows, { pack: pack.collection }));
  }
  { const rows = doItems(game.items, "world"); if (rows.length && !DRY_RUN) await Item.updateDocuments(rows); }
  for (const a of game.actors) { const rows = doItems(a.items, `actor ${a.name}`); if (rows.length && !DRY_RUN) await a.updateEmbeddedDocuments("Item", rows); }
  for (const pack of game.packs.filter(p => mine(p) && p.documentName === "Actor")) {
    for (const a of await pack.getDocuments()) { const rows = doItems(a.items, `${pack.metadata.label} › ${a.name}`); if (rows.length && !DRY_RUN) await unlockedWrite(pack, () => a.updateEmbeddedDocuments("Item", rows)); }
  }
  console.log("[EVASION-TO-GUARD-2026-11-12]", DRY_RUN ? "DRY RUN" : "APPLIED", changes, "item updates\n" + report.join("\n"));
  ui.notifications.info(`Evasion → Guard: ${changes} item updates ${DRY_RUN ? "(dry run — set DRY_RUN = false)" : "applied"}.`);
  return { dryRun: DRY_RUN, changes, report };
})();
